package vn.luma.web;

import java.security.Principal;
import java.util.*;
import jakarta.validation.Valid;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import vn.luma.business.*;

@Controller
public class HoTroController {
    private final HoTroService service;private final TaiKhoanService users;
    public HoTroController(HoTroService service,TaiKhoanService users){this.service=service;this.users=users;}
    private String base(boolean admin){return admin?"/quan-tri/ho-tro":"/tai-khoan/ho-tro";}
    @PostMapping("/tai-khoan/ho-tro/widget/mo") @ResponseBody public Map<String,Object> widgetMo(Principal u){long id=service.mo(u.getName());return Map.of("id",Long.toString(id),"data",service.tinGanNhat(u.getName(),id));}
    @GetMapping("/tai-khoan/ho-tro/widget/{id}") @ResponseBody public org.springframework.http.ResponseEntity<HoTroService.CapNhat> widgetCapNhat(@PathVariable long id,Principal u){return org.springframework.http.ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).body(service.tinGanNhat(u.getName(),id));}
    @PostMapping("/tai-khoan/ho-tro/widget/{id}/tin") @ResponseBody public HoTroService.CapNhat widgetTin(@PathVariable long id,@Valid @RequestBody TinNhanYeuCau message,Principal u){service.gui(u.getName(),id,message,false);return service.tinGanNhat(u.getName(),id);}
    @PostMapping("/tai-khoan/ho-tro/widget/{id}/chuyen") @ResponseBody public HoTroService.CapNhat widgetChuyen(@PathVariable long id,Principal u){service.chuyen(u.getName(),id);return service.tinGanNhat(u.getName(),id);}
    @GetMapping("/tai-khoan/ho-tro") public String cuaToi(@RequestParam(defaultValue="1") int trang,Principal u,Model m){m.addAttribute("cuocTroChuyen",service.cuaToi(u.getName(),trang));m.addAttribute("trang",trang);m.addAttribute("quanTri",false);m.addAttribute("trangThai","");m.addAttribute("cheDo","");return "ho-tro/danh-sach";}
    @PostMapping("/tai-khoan/ho-tro/gui-nhanh") public String guiNhanh(@RequestParam String noiDung,Principal u,RedirectAttributes flash){try{if(noiDung==null||noiDung.isBlank()||noiDung.length()>2000)throw new IllegalArgumentException("Nhập nội dung hỗ trợ, tối đa 2000 ký tự.");return "redirect:/tai-khoan/ho-tro/"+service.moVaGui(u.getName(),noiDung);}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());return "redirect:/tai-khoan/ho-tro";}}
    @PostMapping("/tai-khoan/ho-tro/mo") public String mo(Principal u,RedirectAttributes flash){try{return "redirect:/tai-khoan/ho-tro/"+service.mo(u.getName());}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());return "redirect:/tai-khoan/ho-tro";}}
    @GetMapping("/quan-tri/ho-tro") public String quanTri(@RequestParam(defaultValue="DANG_MO") String trangThai,@RequestParam(defaultValue="") String cheDo,@RequestParam(defaultValue="1") int trang,Principal u,Model m){m.addAttribute("cuocTroChuyen",service.quanTri(u.getName(),trangThai,cheDo,trang));m.addAttribute("trang",trang);m.addAttribute("quanTri",true);m.addAttribute("trangThai",trangThai);m.addAttribute("cheDo",cheDo);return "ho-tro/danh-sach";}
    private String chiTiet(long id,Long before,Principal u,Model m,boolean admin){var c=admin?service.quanTri(u.getName(),id):service.cuaToi(u.getName(),id);var messages=service.tin(u.getName(),id,before,admin);m.addAttribute("cuoc",c);m.addAttribute("tinNhan",messages);m.addAttribute("quanTri",admin);m.addAttribute("duongDan",base(admin)+"/"+id);m.addAttribute("mocCu",messages.size()==50?messages.getFirst().get("MaTinNhan"):null);m.addAttribute("truoc",before);m.addAttribute("laNguoiPhuTrach",Objects.equals(c.get("MaQuanTriPhuTrach"),users.hienTai(u.getName()).maNguoiDung()));if(!m.containsAttribute("form"))m.addAttribute("form",new TinNhanYeuCau(UUID.randomUUID().toString(),""));if(admin && "QuanTri".equals(users.hienTai(u.getName()).vaiTro())){m.addAttribute("luotXuLy",service.xuLy(u.getName(),id));m.addAttribute("kiemDuyet",service.kiemDuyet(u.getName(),id));}return "ho-tro/chi-tiet";}
    @GetMapping("/tai-khoan/ho-tro/{id}") public String chiTietKhach(@PathVariable long id,@RequestParam(required=false) Long truoc,Principal u,Model m){return chiTiet(id,truoc,u,m,false);}
    @GetMapping("/quan-tri/ho-tro/{id}") public String chiTietAdmin(@PathVariable long id,@RequestParam(required=false) Long truoc,Principal u,Model m){return chiTiet(id,truoc,u,m,true);}
    @GetMapping("/tai-khoan/ho-tro/{id}/tin-moi") @ResponseBody public org.springframework.http.ResponseEntity<HoTroService.CapNhat> tinMoi(@PathVariable long id,@RequestParam(defaultValue="0") long sau,Principal u){return org.springframework.http.ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).body(service.tinMoi(u.getName(),id,sau,false));}
    @GetMapping("/quan-tri/ho-tro/{id}/tin-moi") @ResponseBody public org.springframework.http.ResponseEntity<HoTroService.CapNhat> tinMoiAdmin(@PathVariable long id,@RequestParam(defaultValue="0") long sau,Principal u){return org.springframework.http.ResponseEntity.ok().cacheControl(org.springframework.http.CacheControl.noStore()).body(service.tinMoi(u.getName(),id,sau,true));}
    private String gui(long id,TinNhanYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash,boolean admin){if(!errors.hasErrors())try{service.gui(u.getName(),id,f,admin);flash.addFlashAttribute("thongBao","Đã gửi tin nhắn.");return "redirect:"+base(admin)+"/"+id;}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return chiTiet(id,null,u,m,admin);}
    @PostMapping("/tai-khoan/ho-tro/{id}/tin") public String guiKhach(@PathVariable long id,@Valid @ModelAttribute("form") TinNhanYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){return gui(id,f,errors,u,m,flash,false);}
    @PostMapping("/quan-tri/ho-tro/{id}/tin") public String guiAdmin(@PathVariable long id,@Valid @ModelAttribute("form") TinNhanYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){return gui(id,f,errors,u,m,flash,true);}
    private void thaoTac(Runnable action,RedirectAttributes flash,String message){try{action.run();flash.addFlashAttribute("thongBao",message);}catch(IllegalArgumentException ex){flash.addFlashAttribute("loi",ex.getMessage());}}
    @PostMapping("/tai-khoan/ho-tro/{id}/chuyen") public String chuyen(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.chuyen(u.getName(),id),flash,"Đã chuyển yêu cầu cho nhân viên.");return "redirect:/tai-khoan/ho-tro/"+id;}
    @PostMapping("/tai-khoan/ho-tro/{id}/dong") public String dongKhach(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.dong(u.getName(),id,false),flash,"Đã đóng cuộc hỗ trợ. Bạn vẫn có thể đọc lại lịch sử.");return "redirect:/tai-khoan/ho-tro/"+id;}
    @PostMapping("/quan-tri/ho-tro/{id}/nhan") public String nhan(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.nhan(u.getName(),id),flash,"Bạn đã nhận cuộc hỗ trợ.");return "redirect:/quan-tri/ho-tro/"+id;}
    @PostMapping("/quan-tri/ho-tro/{id}/tra-hang-cho") public String tra(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.traHangCho(u.getName(),id),flash,"Đã trả cuộc hỗ trợ về hàng chờ.");return "redirect:/quan-tri/ho-tro/"+id;}
    @PostMapping("/quan-tri/ho-tro/{id}/dong") public String dongAdmin(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.dong(u.getName(),id,true),flash,"Đã đóng cuộc hỗ trợ.");return "redirect:/quan-tri/ho-tro/"+id;}
    @PostMapping("/quan-tri/ho-tro/{id}/kiem-duyet/{turn}") public String kiemDuyet(@PathVariable long id,@PathVariable long turn,@RequestParam String ketQua,@RequestParam String nhanXet,Principal u,RedirectAttributes flash){thaoTac(()->service.kiemDuyet(u.getName(),id,turn,ketQua,nhanXet),flash,"Đã lưu kết quả kiểm duyệt lượt bot.");return "redirect:/quan-tri/ho-tro/"+id;}
    @GetMapping("/quan-tri/tri-thuc") public String triThuc(@RequestParam(defaultValue="1") int trang,Principal u,Model m){m.addAttribute("taiLieu",service.taiLieu(u.getName(),trang));m.addAttribute("trang",trang);return "ho-tro/tri-thuc";}
    @GetMapping("/quan-tri/tri-thuc/moi") public String soan(@RequestParam(required=false) Long tuBan,Principal u,Model m){m.addAttribute("chuDe",service.chuDe(u.getName()));if(!m.containsAttribute("form")){if(tuBan==null)m.addAttribute("form",new TaiLieuHoTroYeuCau(0,"",""));else{var d=service.taiLieu(u.getName(),tuBan);m.addAttribute("form",new TaiLieuHoTroYeuCau(((Number)d.get("MaChuDeHoTro")).longValue(),(String)d.get("TieuDe"),(String)d.get("NoiDungDaSoan")));}}return "ho-tro/tai-lieu-form";}
    @PostMapping("/quan-tri/tri-thuc/moi") public String luuTaiLieu(@Valid @ModelAttribute("form") TaiLieuHoTroYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){if(!errors.hasErrors())try{long saved=service.taoTaiLieu(u.getName(),f);flash.addFlashAttribute("thongBao","Đã tạo bản nháp mới. Đọc và duyệt trước khi bot được dùng.");return "redirect:/quan-tri/tri-thuc/"+saved;}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return soan(null,u,m);}
    @GetMapping("/quan-tri/tri-thuc/{id}") public String taiLieu(@PathVariable long id,Principal u,Model m){m.addAttribute("taiLieu",service.taiLieu(u.getName(),id));return "ho-tro/tai-lieu";}
    @PostMapping("/quan-tri/tri-thuc/{id}/duyet") public String duyet(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.duyet(u.getName(),id),flash,"Đã duyệt phiên bản này và ngừng phiên bản đang dùng trước đó.");return "redirect:/quan-tri/tri-thuc/"+id;}
    @PostMapping("/quan-tri/tri-thuc/{id}/ngung") public String ngung(@PathVariable long id,Principal u,RedirectAttributes flash){thaoTac(()->service.ngung(u.getName(),id),flash,"Đã ngừng sử dụng phiên bản này. Lịch sử nguồn vẫn được giữ.");return "redirect:/quan-tri/tri-thuc/"+id;}
    @GetMapping("/quan-tri/chu-de-ho-tro") public String chuDe(Principal u,Model m){m.addAttribute("chuDe",service.chuDe(u.getName()));return "ho-tro/chu-de";}
    @GetMapping({"/quan-tri/chu-de-ho-tro/moi","/quan-tri/chu-de-ho-tro/{id}"}) public String suaChuDe(@PathVariable(required=false) Long id,Principal u,Model m){var topics=service.chuDe(u.getName());m.addAttribute("maChuDe",id);if(!m.containsAttribute("form")){if(id==null)m.addAttribute("form",new ChuDeHoTroYeuCau("","","",false,true));else{var t=topics.stream().filter(r->((Number)r.get("MaChuDeHoTro")).longValue()==id).findFirst().orElseThrow(()->new KhongTimThayException("Không có chủ đề này."));m.addAttribute("form",new ChuDeHoTroYeuCau((String)t.get("KyHieu"),(String)t.get("TenChuDe"),Objects.toString(t.get("vi_du_form"),""),Boolean.TRUE.equals(t.get("ChuyenNhanVien")),Boolean.TRUE.equals(t.get("DangHoatDong"))));}}return "ho-tro/chu-de-form";}
    @PostMapping({"/quan-tri/chu-de-ho-tro/moi","/quan-tri/chu-de-ho-tro/{id}"}) public String luuChuDe(@PathVariable(required=false) Long id,@Valid @ModelAttribute("form") ChuDeHoTroYeuCau f,BindingResult errors,Principal u,Model m,RedirectAttributes flash){if(!errors.hasErrors())try{long saved=service.luuChuDe(u.getName(),id,f);flash.addFlashAttribute("thongBao","Đã lưu chủ đề và các cụm câu hỏi nhận diện.");return "redirect:/quan-tri/chu-de-ho-tro/"+saved;}catch(IllegalArgumentException ex){m.addAttribute("loi",ex.getMessage());}return suaChuDe(id,u,m);}
}
